import {renderCraftingDetail,craftReceiptText} from '../../../../src/crafting_detail.js';
import {createHouseholdScene} from '../../../../src/household_scene.js';
import {quietPlaceText} from '../../../../src/quiet_place_detail.js';
import {createSettledTextEffects} from '../../../../src/settled_text_effects.js';
const $=s=>document.querySelector(s);
let variant='signal',applying=false;
const initial=()=>({schema:1,view:'craft',selected:'Roasted rat meat',stock:4,bread:5,receipt:'',history:['You arrived at the Village.','Known cooking station · tier 1.'],steps:0,effects:'reduced',mood:'curious',inspected:null,scenario:'ready',sequence:0});
let state=initial();
const effects=createSettledTextEffects({container:$('.work'),readSettings:()=>({effects:state.effects,sound:false,presentation:'inline'})});
function capture(){return {...structuredClone(state),scroll:[...document.querySelectorAll('.body')].map(n=>n.scrollTop),focus:document.activeElement?.id||document.activeElement?.dataset.inspect||null};}
function publish(){if(!applying)parent.postMessage({type:'mockup:state',snapshot:capture()},location.origin);}
function btn(label,run){const b=document.createElement('button');b.textContent=label;b.onclick=run;return b;}
function act(){if(state.stock<1)return;state.stock--;state.sequence++;state.receipt=craftReceiptText({made:1,result_name:'Roasted rat meat',used:[{name:'Rat meat chunks',count:1}],xp:0,skill_id:'Cooking',skill_level:5});state.history.push(state.receipt);render();effects.present({type:'native-craft',eventId:`fixture:${state.sequence}`,subjectId:state.selected,text:'Made 1 Roasted rat meat'},{anchor:$('#craft-detail')});publish();}
function render(){document.body.dataset.variant=variant;document.body.classList.toggle('effects-off',state.effects==='off');$('#effects').value=state.effects;$('#atmosphere').textContent=quietPlaceText({knownVillage:true,roofed:false,raining:state.scenario==='rain',effects:state.effects});$('#work-title').textContent=state.view==='craft'?'Crafting':state.view==='home'?'Home · Cottage':'Here';document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false'));$('#progress').textContent=`${state.steps} manual steps`;$('#stock').replaceChildren(...[['Rat meat chunks',state.stock],['Stale bread',state.bread],['Cheap leather pants [40%]',1],['Prepared survey kit',2],['Wood',3],['Oil lamp · unlit',1]].map(([name,count])=>{const b=btn('',()=>{state.inspected=name;render();publish();});b.textContent=name;const n=document.createElement('b');n.textContent=`×${count}`;b.append(n);b.setAttribute('aria-pressed',String(state.inspected===name));return b;}));$('#item-detail').hidden=!state.inspected;$('#item-detail').textContent=state.inspected?`${state.inspected} · carried fixture stock. Inspecting spends nothing.`:'';$('#inspection').hidden=true;
 const views=$('#views');views.replaceChildren();
 if(state.view==='craft'){const list=document.createElement('div');list.className='recipe-list';list.append(btn('Roasted rat meat',()=>{}),btn('Station · Cooking I',()=>{}));const detail=document.createElement('div');detail.id='craft-detail';views.append(list,detail);renderCraftingDetail(detail,{title:state.selected,requirements:[{label:'Rat meat chunks',have:state.stock,need:1,missing:state.stock<1}],output:{name:state.selected,count:1},chance:100,station:'Cooking · tier 1 fixture',xp:'Not simulated',available:state.stock>0,attempts:state.stock,blocked_reason:'No rat meat remains in fixture stock.',receipt:state.receipt,policy:'Scripted single success. Native odds, XP and batch simulation are outside this study.'},{onCommit:act,onBlocked:()=>{}});detail.querySelectorAll('[data-craft-amount]').forEach(b=>{b.disabled=true;b.title='Batch actions excluded from this fixture';});}
 else if(state.view==='home'){const home=document.createElement('div');home.className='home-scene';const scene=createHouseholdScene();home.append(scene.node);scene.update({subjectKey:'fixture:cottage',animal:{name:'Moss',mood:state.mood,bond:12,posture:state.mood==='content'?'Resting nearby.':'Watching from the doorway.',metAt:10,knownMinutes:20,playVisits:0},hearth:null});const actions=document.createElement('div');actions.id='home-actions';actions.append(btn('Fixture mood · content',()=>{state.mood='content';render();publish();}),btn('Fixture mood · curious',()=>{state.mood='curious';render();publish();}));views.append(home,actions);}
 else{views.append(btn('Try to craft something',()=>navigate('craft')),btn('Homes',()=>navigate('home')));const p=document.createElement('p');p.textContent='Known services, current work and Reports retain their homes. This reduced fixture does not reproduce every native menu.';views.append(p);}
 $('#log').replaceChildren(...state.history.map((t,i)=>{const p=document.createElement('p'),time=document.createElement('small');time.textContent=`Village · fixture occurrence ${i+1}`;p.append(time,document.createTextNode(t));return p;}));$('#status').textContent=state.receipt?'Last result stays in Reports.':'Inspect before committing. Nothing is reserved.';
}
function navigate(view){effects.cancel();state.view=view;render();publish();}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#back').onclick=()=>navigate('here');$('#effects').onchange=()=>{state.effects=$('#effects').value;effects.cancel();render();publish();};$('#practice').onclick=()=>{state.steps++;render();publish();};document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>{const d=$('#inspection');d.hidden=false;d.textContent=b.dataset.inspect+' · known person. Dialogue is outside this fixture.';});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.inspected){state.inspected=null;render();publish();}else navigate('here');}});
window.addEventListener('message',event=>{if(event.source!==parent||event.origin!==location.origin||event.data?.type!=='mockup:command')return;const {id,command,value,variant:next}=event.data;applying=true;try{effects.cancel();if(command==='restore'){if(value?.schema!==1)throw Error('Unsupported fixture');state=structuredClone(value);if(next)variant=next;render();document.querySelectorAll('.body').forEach((n,i)=>n.scrollTop=value.scroll?.[i]||0);if(value.focus)document.getElementById(value.focus)?.focus({preventScroll:true});}else if(command==='variant'){variant=value;document.body.dataset.variant=variant;}else if(command==='scenario'){state=initial();state.scenario=value;if(value==='short')state.stock=0;if(value==='crowded')state.history.push(...Array.from({length:35},(_,i)=>`Scripted practice receipt ${i+1} · same known task.`));render();}else if(command==='text'){document.documentElement.style.setProperty('--text',`${value}px`);document.documentElement.style.setProperty('--body-font',value===21?'StudyGothic21, monospace':'StudyGothic, monospace');document.documentElement.style.setProperty('--ui-type-body',`${value}px`);}else if(command==='step'){state.steps++;render();}parent.postMessage({type:'mockup:reply',id,snapshot:capture()},location.origin);}catch(error){parent.postMessage({type:'mockup:reply',id,error:error.message},location.origin);}finally{applying=false;}});
render();parent.postMessage({type:'mockup:ready'},location.origin);
